419	  @override
420	  Widget build(BuildContext context) {
421	    return BlocListener<PhotoEntryCubit, PhotoCaptureState>(
422	      listener: _onPhotoStateChange,
423	      child: BlocListener<AudioEntryCubit, AudioCaptureState>(
424	        listener: _onAudioStateChange,
425	        // Review finding: `isSaving` below previously only read
426	        // `TextEntryCubit`'s state, so the tab bar/"x" close button
427	        // stayed tappable while an *audio* save was in flight
428	        // (`AudioTranscribed.saving == true`) — the same race Story
429	        // 3.1's own review fixed for the Texto tab, just unguarded on
430	        // the Áudio side. Wrapping in this `BlocBuilder` makes the whole
431	        // subtree rebuild on an `AudioEntryCubit` state change too, not
432	        // only a `TextEntryCubit` one. Same rationale — spec-3-3 —
433	        // extends this to `PhotoEntryCubit`'s own saving flag via the
434	        // nested `BlocBuilder` below.
435	        child: BlocBuilder<AudioEntryCubit, AudioCaptureState>(
436	          builder: (context, audioState) {
437	            final isAudioSaving =
438	                audioState is AudioTranscribed && audioState.saving;
439	            return BlocBuilder<PhotoEntryCubit, PhotoCaptureState>(
440	              builder: (context, photoState) {
441	                final isPhotoSaving =
442	                    photoState is PhotoRecognized && photoState.saving;
443	                return BlocConsumer<TextEntryCubit, TextEntryState>(
444	                  listener: _onTextEntryStateChange,
445	                  builder: (context, state) {
446	                    final isSaving =
447	                        state is TextEntrySaving ||
448	                        isAudioSaving ||
449	                        isPhotoSaving;
450	                    return Container(
451	                      padding: DesignTokens.screenPadding,
452	                      decoration: const BoxDecoration(
453	                        color: DesignTokens.colorSurfaceElevated,
454	                        borderRadius: BorderRadius.vertical(
455	                          top: Radius.circular(DesignTokens.radiusLg),
456	                        ),
457	                        boxShadow: DesignTokens.elevation2,
458	                      ),
459	                      child: Padding(
460	                        // Keeps the Texto field clear of the on-screen
461	                        // keyboard — the sheet is
462	                        // `isScrollControlled: true`, so it already
463	                        // grows to fit; this is the standard companion
464	                        // fix for the keyboard inset itself.
465	                        padding: EdgeInsets.only(
466	                          bottom: MediaQuery.of(context).viewInsets.bottom,
467	                        ),
468	                        child: SafeArea(
469	                          top: false,
470	                          child: Column(
471	                            mainAxisSize: MainAxisSize.min,
472	                            crossAxisAlignment: CrossAxisAlignment.stretch,
473	                            children: [
474	                              Row(
475	                                crossAxisAlignment: CrossAxisAlignment.center,
476	                                children: [
477	                                  Expanded(
478	                                    child: _TabBar(
479	                                      activeTab: state.activeTab,
480	                                      isSaving: isSaving,
481	                                    ),
482	                                  ),
483	                                  const SizedBox(width: DesignTokens.spacingSm),
484	                                  _CloseButton(isSaving: isSaving),
485	                                ],
486	                              ),
487	                              const SizedBox(height: DesignTokens.spacingMd),
488	                              switch (state.activeTab) {
489	                                CaptureTab.texto => _TextoTab(
490	                                  controller: _textController,
491	                                  state: state,
492	                                ),
493	                                CaptureTab.audio => _AudioTab(
494	                                  controller: _audioTextController,
495	                                ),
496	                                CaptureTab.foto => _FotoTab(
497	                                  controller: _photoTextController,
498	                                ),
499	                              },
500	                            ],
501	                          ),
502	                        ),
503	                      ),
504	                    );
505	                  },
506	                );
507	              },
508	            );
509	          },
510	        ),
511	      ),
512	    );
513	  }
514	}
