1046	/// renders a static placeholder pattern at [opacity] instead of
1047	/// subscribing — the "frozen" rendering `_AudioProcessingView` uses.
1048	class _Waveform extends StatefulWidget {
1049	  const _Waveform({required this.amplitudeStream, required this.opacity});
1050	
