1058	class _WaveformState extends State<_Waveform> {
1059	  // `growable: true` — `build()` below reads this with `removeAt`/`add`
1060	  // on every new amplitude sample, which `List.filled`'s own default
1061	  // fixed-length list doesn't support.
1062	  final List<double> _samples = List.filled(
1063	    _waveformBarCount,
1064	    0.1,
1065	    growable: true,
1066	  );
1067	  StreamSubscription<double>? _subscription;
1068	
1069	  @override
1070	  void initState() {
1071	    super.initState();
1072	    _subscription = widget.amplitudeStream?.listen(
1073	      (amplitude) {
1074	        if (!mounted) {
1075	          return;
1076	        }
1077	        setState(() {
1078	          _samples.removeAt(0);
1079	          // `num.clamp` returns `num`, not `double` — `_samples` is
1080	          // `List<double>`.
1081	          _samples.add(amplitude.clamp(0.1, 1.0).toDouble());
1082	        });
1083	      },
1084	      // Review finding: an unhandled `onError` turns a native amplitude-
1085	      // stream error into an uncaught async exception — the waveform
1086	      // just stays frozen on its last sample instead, no worse than the
1087	      // already-handled "no live stream" (frozen/processing) case.
1088	      onError: (_) {},
1089	    );
1090	  }
1091	
1092	  @override
1093	  void dispose() {
1094	    _subscription?.cancel();
1095	    super.dispose();
1096	  }
