1109	              AnimatedContainer(
1110	                duration: DesignTokens.durationSheetUp,
1111	                width: DesignTokens.spacingXs,
1112	                height: DesignTokens.spacing2xl * _samples[i],
1113	                decoration: const BoxDecoration(
